var builder = WebApplication.CreateBuilder(args);
var app = builder.Build();

app.UseStaticFiles(); // serves from wwwroot by default

app.MapGet("/", () => "Hello World!");
app.Run();

app.UseStaticFiles(new StaticFileOptions
{
    OnPrepareResponse = ctx =>
    {
        const int durationInSeconds = 60 * 60 * 24 * 365; // 1 year
        ctx.Context.Response.Headers.CacheControl = $
            "public,max-age={durationInSeconds}";
    }
});

var uploadsPath = Path.Combine(
    builder.Environment.ContentRootPath, "UserUploads");

if (!Directory.Exists(uploadsPath))
{
    Directory.CreateDirectory(uploadsPath);
}

app.UseStaticFiles(new StaticFileOptions
{
    FileProvider = new PhysicalFileProvider(uploadsPath),
    RequestPath = "/uploads"
});

// Now /uploads/myphoto.jpg maps to UserUploads/myphoto.jpg

// Program.cs
builder.Services.AddControllers(options =>
{
    options.CacheProfiles.Add("ShortLived", new CacheProfile
    {
        Duration = TimeSpan.FromSeconds(30).TotalSeconds,
        Location = ResponseCacheLocation.Client,
        NoStore = false
    });
});

builder.Services.AddResponseCaching();

var app = builder.Build();
app.UseResponseCaching();
app.MapControllers();
app.Run();

// ProductsController.cs
[ResponseCache(CacheProfileName = "ShortLived")]
[HttpGet]
public IActionResult GetFeatured()
{
    var products = _repo.GetFeatured();
    return Ok(products);
}

[ResponseCache(Duration = 60, VaryByQueryKeys = new[] { "category", "page" })]
[HttpGet("/api/products")]
public IActionResult GetProducts(string category, int page)
{
    var results = _repo.GetProducts(category, page);
    return Ok(results);
}
